s32 guRandom();                                     /* extern */

/* Returns a pseudo-random float in [0, max) using the low 16 bits of guRandom. */ f32 randomFloatUpTo(f32 max) {
    s32 rand;

    rand = guRandom();
    return (f32) (rand % 0x10000) * 0.000015258789f * max;
}
